"""Cantor / beth tower demo: T_0 = base, T_{n+1} = 2^{T_n}."""
from __future__ import annotations

import sys
from typing import List

sys.set_int_max_str_digits(1_000_000)


def cantor_tower(base: int, height: int) -> List[int]:
    tower: List[int] = [base]
    for _ in range(height):
        tower.append(2 ** tower[-1])
    return tower


def is_strictly_increasing(seq: List[int]) -> bool:
    return all(seq[i] < seq[i + 1] for i in range(len(seq) - 1))


def main() -> None:
    tower = cantor_tower(base=2, height=4)
    for n, t in enumerate(tower):
        shown = str(t) if t < 10 ** 12 else f"a {len(str(t))}-digit number"
        print(f"T_{n} = {shown}")
    print("strictly increasing?", is_strictly_increasing(tower))
    for n in range(6):
        print(f"|S|={n} < |P(S)|=2^{n}={2 ** n}: {n < 2 ** n}")


if __name__ == "__main__":
    main()

"""Cofinality classifier and the constraint c != aleph_omega."""
from __future__ import annotations

from typing import Tuple


def cofinality_index(aleph_index: str) -> Tuple[str, str]:
    if aleph_index == "0":
        return ("regular", "aleph_0")
    if aleph_index.startswith("succ:"):
        return ("regular", aleph_index[5:] + "+1")
    if aleph_index == "omega":
        return ("singular", "aleph_0")
    if aleph_index == "cont":
        return ("regular-cofinality (> aleph_0)", "uncountable")
    raise ValueError(aleph_index)


def continuum_ne_aleph_omega() -> bool:
    return cofinality_index("cont")[1] != cofinality_index("omega")[1]


def main() -> None:
    for idx, name in [("0", "aleph_0"), ("succ:aleph_0", "aleph_1"),
                      ("omega", "aleph_omega"), ("cont", "c")]:
        print(name, cofinality_index(idx))
    print("c != aleph_omega:", continuum_ne_aleph_omega())


if __name__ == "__main__":
    main()

