        if not (T[i] < T[i+1]): return false   # Cantor: T[i] < 2^{T[i]}
    return true

function COFINALITY(index):
    if index == '0':            return ('regular',  'aleph_0')
    if index starts with 'succ':return ('regular',  index)      # AC: successors regular
    if index == 'omega':        return ('singular', 'aleph_0')  # aleph_omega = sup_n aleph_n
    if index == 'cont':         return ('regular',  'uncountable')  # Koenig: cof(2^aleph_0) > aleph_0

function CONTINUUM_NE_ALEPH_OMEGA():
    return COFINALITY('cont').cof != COFINALITY('omega').cof

