"""Cofinality Decision Procedure for Aleph-Indexed Cardinals."""
from __future__ import annotations

from typing import Tuple


def cofinality(index: str) -> Tuple[str, str]:
    """Classify an aleph-indexed cardinal as regular/singular and give cofinality.

    '0' -> aleph_0; 'succ:<name>' -> successor cardinal (regular under AC);
    'omega' -> aleph_omega (singular, cof aleph_0); 'cont' -> continuum
    (uncountable cofinality by Koenig's theorem).
    """
    if index == "0":
        return ("regular", "aleph_0")
    if index.startswith("succ:"):
        return ("regular", index[5:] + "+1")
    if index == "omega":
        return ("singular", "aleph_0")
    if index == "cont":
        return ("regular", "uncountable")
    raise ValueError(f"unknown index: {index}")


def continuum_ne_aleph_omega() -> bool:
    """c != aleph_omega since cof(c) > aleph_0 = cof(aleph_omega)."""
    return cofinality("cont")[1] != cofinality("omega")[1]


if __name__ == "__main__":
    print(cofinality("cont"), cofinality("omega"))
    print("c != aleph_omega:", continuum_ne_aleph_omega())
